54	/// A generalized parser for binary operations. This parses the different forms
55	/// of 'printBinaryOp' below.
56	static mlir::ParseResult parseBinaryOp(mlir::OpAsmParser &parser,
57	                                       mlir::OperationState &result) {
58	  SmallVector<mlir::OpAsmParser::UnresolvedOperand, 2> operands;
59	  SMLoc operandsLoc = parser.getCurrentLocation();
60	  Type type;
61	  if (parser.parseOperandList(operands, /*requiredOperandCount=*/2) ||
62	      parser.parseOptionalAttrDict(result.attributes) ||
63	      parser.parseColonType(type))
64	    return mlir::failure();
65	
66	  // If the type is a function type, it contains the input and result types of
67	  // this operation.
68	  if (FunctionType funcType = llvm::dyn_cast<FunctionType>(type)) {
69	    if (parser.resolveOperands(operands, funcType.getInputs(), operandsLoc,
70	                               result.operands))
71	      return mlir::failure();
72	    result.addTypes(funcType.getResults());
73	    return mlir::success();
74	  }
75	
76	  // Otherwise, the parsed type is the type of both operands and results.
77	  if (parser.resolveOperands(operands, type, result.operands))
78	    return mlir::failure();
79	  result.addTypes(type);
80	  return mlir::success();
81	}
82	
83	/// A generalized printer for binary operations. It prints in two different
84	/// forms depending on if all of the types match.
85	static void printBinaryOp(mlir::OpAsmPrinter &printer, mlir::Operation *op) {
86	  printer << " " << op->getOperands();
87	  printer.printOptionalAttrDict(op->getAttrs());
88	  printer << " : ";
89	
90	  // If all of the types are the same, print the type directly.
91	  Type resultType = *op->result_type_begin();
92	  if (llvm::all_of(op->getOperandTypes(),
93	                   [=](Type type) { return type == resultType; })) {
94	    printer << resultType;
95	    return;
96	  }
97	
98	  // Otherwise, print a functional type.
99	  printer.printFunctionalType(op->getOperandTypes(), op->getResultTypes());
100	}
