102	//===----------------------------------------------------------------------===//
103	// ConstantOp
104	//===----------------------------------------------------------------------===//
105	
106	/// Build a constant operation.
107	/// The builder is passed as an argument, so is the state that this method is
108	/// expected to fill in order to build the operation.
109	void ConstantOp::build(mlir::OpBuilder &builder, mlir::OperationState &state,
110	                       double value) {
111	  auto dataType = RankedTensorType::get({}, builder.getF64Type());
112	  auto dataAttribute = DenseElementsAttr::get(dataType, value);
113	  ConstantOp::build(builder, state, dataType, dataAttribute);
114	}
