116	/// The 'OpAsmParser' class provides a collection of methods for parsing
117	/// various punctuation, as well as attributes, operands, types, etc. Each of
118	/// these methods returns a `ParseResult`. This class is a wrapper around
119	/// `LogicalResult` that can be converted to a boolean `true` value on failure,
120	/// or `false` on success. This allows for easily chaining together a set of
121	/// parser rules. These rules are used to populate an `mlir::OperationState`
122	/// similarly to the `build` methods described above.
123	mlir::ParseResult ConstantOp::parse(mlir::OpAsmParser &parser,
124	                                    mlir::OperationState &result) {
125	  mlir::DenseElementsAttr value;
126	  if (parser.parseOptionalAttrDict(result.attributes) ||
127	      parser.parseAttribute(value, "value", result.attributes))
128	    return failure();
129	
130	  result.addTypes(value.getType());
131	  return success();
132	}
133	
134	/// The 'OpAsmPrinter' class is a stream that allows for formatting
135	/// strings, attributes, operands, types, etc.
136	void ConstantOp::print(mlir::OpAsmPrinter &printer) {
137	  printer << " ";
138	  printer.printOptionalAttrDict((*this)->getAttrs(), /*elidedAttrs=*/{"value"});
139	  printer << getValue();
140	}
141	
142	/// Verifier for the constant operation. This corresponds to the
143	/// `let hasVerifier = 1` in the op definition.
144	llvm::LogicalResult ConstantOp::verify() {
145	  // If the return type of the constant is not an unranked tensor, the shape
146	  // must match the shape of the attribute holding the data.
147	  auto resultType = llvm::dyn_cast<mlir::RankedTensorType>(getResult().getType());
148	  if (!resultType)
149	    return success();
150	
151	  // Check that the rank of the attribute type matches the rank of the constant
152	  // result type.
153	  auto attrType = llvm::cast<mlir::RankedTensorType>(getValue().getType());
154	  if (attrType.getRank() != resultType.getRank()) {
155	    return emitOpError("return type must match the one of the attached value "
156	                       "attribute: ")
157	           << attrType.getRank() << " != " << resultType.getRank();
158	  }
159	
160	  // Check that each of the dimensions match between the two types.
161	  for (int dim = 0, dimE = attrType.getRank(); dim < dimE; ++dim) {
162	    if (attrType.getShape()[dim] != resultType.getShape()[dim]) {
163	      return emitOpError(
164	                 "return type shape mismatches its attribute at dimension ")
165	             << dim << ": " << attrType.getShape()[dim]
166	             << " != " << resultType.getShape()[dim];
167	    }
168	  }
169	  return mlir::success();
170	}
