258	
259	llvm::LogicalResult ReturnOp::verify() {
260	  // We know that the parent operation is a function, because of the 'HasParent'
261	  // trait attached to the operation definition.
262	  auto function = cast<FuncOp>((*this)->getParentOp());
263	
264	  /// ReturnOps can only have a single optional operand.
265	  if (getNumOperands() > 1)
266	    return emitOpError() << "expects at most 1 return operand";
267	
268	  // The operand number and types must match the function signature.
269	  const auto &results = function.getFunctionType().getResults();
270	  if (getNumOperands() != results.size())
271	    return emitOpError() << "does not return the same number of values ("
272	                         << getNumOperands() << ") as the enclosing function ("
273	                         << results.size() << ")";
274	
275	  // If the operation does not have an input, we are done.
276	  if (!hasOperand())
277	    return mlir::success();
278	
279	  auto inputType = *operand_type_begin();
280	  auto resultType = results.front();
281	
282	  // Check that the result type of the function matches the operand type.
283	  if (inputType == resultType || llvm::isa<mlir::UnrankedTensorType>(inputType) ||
284	      llvm::isa<mlir::UnrankedTensorType>(resultType))
285	    return mlir::success();
286	
287	  return emitError() << "type of return operand (" << inputType
288	                     << ") doesn't match function result type (" << resultType
289	                     << ")";
290	}
