292	//===----------------------------------------------------------------------===//
293	// TransposeOp
294	//===----------------------------------------------------------------------===//
295	
296	void TransposeOp::build(mlir::OpBuilder &builder, mlir::OperationState &state,
297	                        mlir::Value value) {
