299	  state.addOperands(value);
300	}
301	
302	llvm::LogicalResult TransposeOp::verify() {
303	  auto inputType = llvm::dyn_cast<RankedTensorType>(getOperand().getType());
304	  auto resultType = llvm::dyn_cast<RankedTensorType>(getType());
305	  if (!inputType || !resultType)
306	    return mlir::success();
307	
308	  auto inputShape = inputType.getShape();
309	  if (!std::equal(inputShape.begin(), inputShape.end(),
310	                  resultType.getShape().rbegin())) {
311	    return emitError()
312	           << "expected result shape to be a transpose of the input";
313	  }
314	  return mlir::success();
315	}
